		//获取本机的打印机列表。列表中的第一项就是默认打印机。 
        public void GetLocalPrinters()
        {
			DataTable dt = new DataTable();
            DataRow dr = null;

            dt.Columns.Add("Printer");
			
			dr=dt.NewRow();
			dr["Printer"] = "";
			dt.Rows.Add(dr);

            foreach (String fPrinterName in PrinterSettings.InstalledPrinters)
            {
                dr = dt.NewRow();

                dr["Printer"] = fPrinterName;

                dt.Rows.Add(dr);
            }

            ds.Tables.Add(dt);
        }

        /// <summary>
        /// 脚本对象实例化时加载时的方法
