        public void ScriptLoad()
        {
        	//to do..
			
			//获取本地打印机
			GetLocalPrinters();
			
			//打印机列表赋值
			Scripter.SetParameterDataSet("CustomerSNPrinter",ds);
			
			//实例化网格
			grid=(Infragistics.Win.UltraWinGrid.UltraGrid)Scripter.MESTxnPanel.Controls["LotInfo"] ;
			
