        /// <summary>
        /// 容器中按钮通用触发事件
        /// </summary>
        /// <param name="ButtonName">按钮名</param>
        public void ButtonClick(string ButtonName)
        {
		    //to do..
				
			//设置客户SN默认打印机
			if (ButtonName=="SetSNPrinter")
			{
            	SetDefaultPrinter(Scripter.GetParameterValue("CustomerSNPrinter"));
			}
			
			#region 选中行
			if (ButtonName=="SelRow")
			{	
				try
				{							
					string NextItemName=Scripter.GetParameterValue("NextItemName");
					
					for(int i=0;i<grid.Rows.Count;i++)
					{
						if (Convert.ToString(grid.Rows[i].Cells["CollectItemName"].Value)==NextItemName)
						{
							grid.Rows[i].Selected =true;
						}
						else
						{
							grid.Rows[i].Selected =false;
						}
					}
				}
				catch{}
			}
			#endregion	
			
			if(ButtonName=="LockData")
			{
				if(Scripter.GetParameterValue("IsLock")=="")
				{
					Scripter.SetControlStyle("OrderName","[Enable|0]");
					Scripter.SetControlStyle("MOName","[Enable|0]");
					Scripter.SetControlStyle("Operator","[Enable|0]");
					Scripter.SetParameterValue("IsLock","Y");
				}
				else
				{
					Scripter.SetControlStyle("OrderName","[Enable|1]");
					Scripter.SetControlStyle("MOName","[Enable|1]");
					Scripter.SetControlStyle("Operator","[Enable|1]");
					Scripter.SetParameterValue("IsLock","");
				}
			}
			
        }

